assert len(cases)==14 and len({c['slug'] for c in cases})==14
outroot=Path('src/demos/life')
existing=[str(outroot/c['slug']) for c in cases if (outroot/c['slug']).exists()]
if existing:
 raise SystemExit('Refusing to overwrite existing lessons: '+', '.join(existing))
for c in cases:
 p=outroot/c['slug']; p.mkdir(parents=True)
 shift=c['id'] % 3
 options=c['options'][shift:]+c['options'][:shift]
 lesson={'question':c['q'],'options':options,'answer':options.index(c['options'][c['answer']]),'explanation':c['explain']}
 js=json.dumps(lesson,ensure_ascii=False,indent=2)
 code='''"use client";
import { useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
const model = MODEL;
export default function Demo({slug}:{slug:string}) {
  const [shown,setShown] = useState(false);
  return <Lesson slug={slug} predict={{question:model.question,options:model.options,answer:model.answer}} exploreHint="Open the schematic evidence." reveal={()=><p>{model.explanation}</p>}>
  {({locked,interact})=><div>
    <svg viewBox="0 0 340 170" className="stage-svg" role="img" aria-label={shown ? model.explanation : "Schematic evidence hidden until exploration."}>
      {shown ? <g>AFTER</g> : <g>BEFORE</g>}
    </svg>
    <Row><Control disabled={locked || shown} onClick={()=>{setShown(true);interact();}}>Explore the evidence</Control></Row>
    <p style={{fontSize:"0.8rem",color:"var(--muted)",textAlign:"center",margin:"4px 0"}}>CAPTION</p>
  </div>}
  </Lesson>;
}
'''.replace('MODEL',js).replace('AFTER',c['after']).replace('BEFORE',c['before']).replace('CAPTION',c['caption'])
 p.joinpath('Demo.tsx').write_text(code)
